"""Native Vercel FastAPI entrypoint; API paths are preserved without rewrites."""

from fastapi.staticfiles import StaticFiles

from server.api import app

# Unlike files present in the Git checkout, these modules are generated by the
# build command. Declare their directory so the native Python builder traces
# it into the deployment as well as serving the source-controlled public files.
app.mount("/assets", StaticFiles(directory="public/assets", check_dir=False), name="frontend-assets")

__all__ = ["app"]
